  "texting.use_case": "{club} is a padel club. It texts its own members, who say yes to texts in the club's app, only about their own bookings and places: a place that opened up for them from a waitlist and must be taken by a deadline, or a booking or class the club cancelled or moved. It also texts one-time codes that a person asks for, to confirm their number or to sign in. It never sends marketing or club news by text.",
  "texting.opt_in_flow": "Opt-in is a web form in the club's app (Profile, Texts). A member first confirms their mobile number with a texted code, then ticks an unticked box that reads: \"{consent}\" Each yes is stored with the time, the wording's version and the device. Replying STOP stops all messages; HELP gets the club's name and how to reach it. A page showing the form: {page}",
  "doctor.texts.no_sender": "Texts: the Twilio account is set, but nothing to text from yet. Register a toll-free number with openpadel texting plan, or name one in KUMI_TWILIO_MESSAGING_SERVICE_SID (or KUMI_TWILIO_FROM).",
