  "ui.moving_group_never": "Never moves",
  "ui.moving_playtomic_comes": "Bookings on the courts you link, held here so no court is sold twice\nAn archive of every booking it reads, from three months back, on each member's page\nUpcoming player bookings, for you to take over at the switch-over\nPlayers with their wallets and memberships, read when you ask",
  "ui.moving_playtomic_file": "Members from the customer export: name, email, phone, a yes to club news, Playtomic ID and level (provisional)\nWallets and memberships from the same export, if the API isn't on",
  "ui.moving_playtomic_never": "Card details: members add a card the first time they pay here\nClasses and courses already sold: they run out in Playtomic",
  "ui.moving_playbypoint_comes": "Nothing by itself: Playbypoint has no way for another system to read the club's data, so its reports come over as files",
  "ui.moving_playbypoint_file": "Members from its All Players report: name, email and phone (and a level, NPRP, from the users list in Customers, Import)\nMemberships and club credit from its Memberships report (and a wallet balance column, if a report has one)\nUpcoming bookings from its Booking Details report\nProgram sign-ups from its Program Attendance report, into programs you set up here",
  "ui.moving_playbypoint_never": "Card details: members add a card the first time they pay here\nPackages and booking passes: Playbypoint documents no export of them, so set them up here as passes\nWhat was paid there: it stays there, and so does any refund of it",
  "ui.moving_spreadsheet_comes": "Nothing by itself",
  "ui.moving_spreadsheet_file": "Members: name, email, language, phone and a yes to club news, from a CSV or Excel file",
  "ui.moving_spreadsheet_never": "Card details, from any system\nMemberships, credit and bookings: set them up here",
  "ui.moving_playbypoint_unverified": "Playbypoint doesn't publish its reports' columns, so they're read by the names its help pages show (Player, Email, Plan, Paid Through, Court, Start, End, Players, Program). They haven't been checked against a real Playbypoint export yet: look at each preview's count and the lines it leaves out before you confirm.",
  "ui.moving_keys": "Playtomic's keys",
  "ui.moving_keys_help": "The owner types these three into /etc/kumi/kumi.env on the server, from Playtomic's Third Party API ({product} never shows them). The setup guide's Playtomic page says how.",
