  "ui.moving_source_courtreserve_how": "Its reports, as Excel files: members, memberships, credit, reservations and events",
  "ui.moving_courtreserve_comes": "Nothing by itself: its reports come over as files the owner exports",
  "ui.moving_courtreserve_file": "Members from its Members report: name, email, phone, member number and a yes to marketing email where it says so\nMemberships, with the date each is paid through, from the Members or Membership report\nClub credit from the Account Credit column, as credit the club owes, never as a payment\nUpcoming bookings from its Reservations report\nEvent sign-ups from its Event Registrant Detail report, into programs you set up here",
  "ui.moving_courtreserve_never": "Card details: members add a card the first time they pay here\nPackages (punch cards): set them up here as passes\nWhat was paid there: it stays there, and so does any refund of it",
  "ui.moving_courtreserve_unverified": "CourtReserve doesn't publish its exports' columns, so they're read by the names its member import template and help pages use (First Name, Last Name, Email, Member #, Membership Name, Account Credit, Courts, Start Time). They haven't been checked against a real CourtReserve export yet: look at each preview's count and the lines it leaves out before you confirm.",
